                .andExpect(jsonPath("$.checkpoints[0].checkpointCode").value("p1"))
                .andExpect(jsonPath("$.checkpoints[2].checkpointCode").value("p3"));

        // 乱序提交：b 先 p3 再 p1
        mockMvc.perform(post("/api/races/r/runners/b/timings")
