415	    @Override
416	    @Transactional
417	    public ServiceResult createTeam(String raceId, CreateTeamRequest request) {
418	        // 成员集合换序视为同参：摘要前按参赛号字典序规范化。
419	        List<String> normalizedBibs = new ArrayList<>(request.memberBibs());
420	        normalizedBibs.sort(String::compareTo);
421	        return withIdempotency(request.requestId(), "CREATE_TEAM",
422	                orderedParams(
423	                        "raceId", raceId,
424	                        "teamCode", request.teamCode(),
425	                        "expectedVersion", request.expectedVersion(),
426	                        "memberBibs", normalizedBibs),
427	                () -> {
428	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
429	                    List<String> bibs = request.memberBibs();
430	                    if (bibs.size() < 3 || bibs.size() > 5) {
431	                        throw new BadRequestException("团队成员数量必须在 3~5 之间");
432	                    }
433	                    if (new java.util.HashSet<>(bibs).size() != bibs.size()) {
434	                        throw new BadRequestException("团队成员参赛号必须互不重复");
435	                    }
436	                    // 冻结条件：赛事一旦出现任何完赛计时或分段记录，团队配置全部冻结；
437	                    // 撤销处罚不会清除这些记录，因此不能借此重新开放。
438	                    if (repository.countFinishedRunners(raceId) > 0
439	                            || repository.countTimings(raceId) > 0) {
440	                        throw new ConflictException(
441	                                "赛事已出现完赛计时或分段记录，团队配置已冻结: " + raceId);
442	                    }
443	                    if (repository.findTeam(raceId, request.teamCode()).isPresent()) {
444	                        throw new ConflictException("团队代码已存在: " + request.teamCode());
445	                    }
446	                    // 成员必须全部已登记（不存在 -> 404），且同一选手最多属于一队（冲突 -> 409）。
447	                    for (String bib : bibs) {
448	                        requireRunner(raceId, bib);
449	                    }
450	                    List<TeamView> existingTeams = repository.findTeams(raceId);
451	                    java.util.Set<String> assigned = new java.util.HashSet<>();
452	                    for (TeamView team : existingTeams) {
453	                        assigned.addAll(team.bibs());
454	                    }
455	                    for (String bib : bibs) {
456	                        if (assigned.contains(bib)) {
457	                            throw new ConflictException(
458	                                    "选手已属于其他团队，不能重复入队: " + bib);
459	                        }
460	                    }
461	
462	                    bumpVersion(race, request.expectedVersion());
463	                    long now = clock.millis();
464	                    try {
465	                        repository.insertTeam(new TeamRow(request.teamCode(), raceId, now));
466	                        repository.insertTeamMembers(bibs.stream()
467	                                .map(bib -> new TeamMemberRow(raceId, request.teamCode(), bib))
468	                                .toList());
469	                    } catch (DuplicateKeyException ex) {
470	                        if (constraintMatches(ex, "uk_team_member_race_bib")
471	                                || constraintMatches(ex, "pk_team_member")) {
472	                            throw new ConflictException("选手已属于其他团队，不能重复入队");
473	                        }
474	                        throw new ConflictException("团队代码已存在: " + request.teamCode());
475	                    }
476	                    // 创建时赛事无任何完赛计时，全部成员必为未排名，团队为 INCOMPLETE。
477	                    List<ResultEntry> entries = ResultCalculator.compute(
478	                            repository.findRunners(raceId),
479	                            repository.findPenalties(raceId),
480	                            repository.findCheckpoints(raceId),
481	                            repository.findAllTimings(raceId));
482	                    List<TeamResult> results = TeamCalculator.compute(
483	                            List.of(new TeamView(request.teamCode(), normalizedBibs)), entries);
484	                    return ServiceResult.created(
485	                            ResponseMapper.toTeamResponse(results.getFirst()));
486	                });
487	    }
