489	    @Override
490	    @Transactional(readOnly = true)
491	    public TeamsResponse getTeams(String raceId) {
492	        RaceRow race = repository.findRace(raceId)
493	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
494	        if (race.status() == RaceStatus.SEALED) {
495	            // 封榜后只返回同版本快照；封榜前没有团队的赛事返回空团队列表，不补造队伍。
496	            Long sealedAt = repository.findSnapshot(raceId)
497	                    .map(SnapshotRow::sealedAt)
498	                    .orElse(null);
499	            return repository.findTeamSnapshot(raceId)
500	                    .map(ResponseMapper::snapshotTeams)
501	                    .orElseGet(() -> new TeamsResponse(
502	                            raceId, race.version(), RaceStatus.SEALED, sealedAt, List.of()));
503	        }
504	        List<ResultEntry> entries = ResultCalculator.compute(
505	                repository.findRunners(raceId),
506	                repository.findPenalties(raceId),
507	                repository.findCheckpoints(raceId),
508	                repository.findAllTimings(raceId));
509	        return ResponseMapper.liveTeams(
510	                race, repository.findTeams(raceId), entries);
511	    }
