    assertThat(before.status()).isEqualTo(TeamStatus.INCOMPLETE);
    assertThat(before.members()).extracting(TeamMemberResponse::status)
            .containsOnly(EntryStatus.MISSING_CHECKPOINT);

    // 为每人补齐 p1、p2 分段（v9 -> v15）。
